  const losses: any[] = d.losses || [];
  const claims: any[] = d.claims || [];
  const totalPolicies = dashboard.policies ?? policies.length;
  const totalCoverage = dashboard.exposure ?? policies.reduce((sum: number, p: any) => sum + Number(p.sumInsured || 0), 0);
  const pendingAssessments = losses.filter((l: any) => l.status === "SUBMITTED").length;
  const claimsAwaitingReview = claims.filter((c: any) => ["INITIATED", "UNDER_REVIEW"].includes(c.status)).length;
