      <div className="stat-card overview-metric"><div className="overview-metric-icon lilac"><Banknote size={18} /></div><div className="stat-copy"><span>Pending disbursement</span><strong>{query.loading ? "—" : pendingDisbursement}</strong><small className="muted">Approved, awaiting DBT</small></div></div>
